", "t": [["write_file", "{"path":"D:\\Projects\\local_ai\\strata-lab\\runs\\work\\hermes\\jsondiff-1794053379\\jsondiff.py","content":"import json\n\n\ndef _fmt(value):\n    return json.dumps(value, sort_keys=True)\n\n\ndef _equal(a, b):\n    # Same type and compare equal (so 1, 1.0, True and \"1\" all differ).\n    return type(a) is type(b) and a == b\n\n\ndef _diff(a, b, path):\n    out = []\n    if type(a) is type(b):\n        if isinstance(a, dict):\n            for key in a:\n                if key in b:\n                    out.extend(_diff(a[key], b[key], path + \".\" + key))\n                else:\n                    out.append(\"- %s.%s: %s\" % (path, key, _fmt(a[key])))\n            for key in b:\n                if key not in a:\n                    out.append(\"+ %s.%s: %s\" % (path, key, _fmt(b[key])))\n            return out\n        if isinstance(a, list):\n            common = min(len(a), len(b))\n            for i in range(common):\n                out.extend(_diff(a[i], b[i], \"%s[%d]\" % (path, i)))\n            for i in range(common, len(a)):\n                out.append(\"- %s[%d]: %s\" % (path, i, _fmt(a[i])))\n            for i in range(common, len(b)):\n                out.append(\"+ %s[%d]: %s\" % (path, i, _fmt(b[i])))\n            return out\n    if _equal(a, b):\n        return out\n    out.append(\"~ %s: %s -> %s\" % (path, _fmt(a), _fmt(b)))\n    return out\n\n\ndef diff(a, b):\n    return sorted(_diff(a, b, \"$\"))\n"}"]]}

